//! 🛂️ Original decoder admission and retirement survive receiving refusal.
use crate::native_decoding::{NativeDecodeControl,NativeDecodeAllocation,NativeForwardedDecodeControl,NativeForwardedDecodeContinuation,NativeDecodeRetirementRecipient};
use crate::{ValueError,ValueRefusalKind};
use semio_framework_test_fixtures::fixture_text;
use std::sync::atomic::{AtomicUsize,Ordering};
fn fixture()->serde_json::Value{serde_json::from_str(fixture_text!("../../../🛂️allocation/🧪️tests/🧫️fixtures/🔣️.json")).unwrap()}
#[test]
fn decoder_original_port_admits_every_small_span_across_receiving_hops(){
 let law=fixture();let ceiling=law["ceiling"].as_u64().unwrap()as usize;let prior:Vec<u8>=serde_json::from_value(law["prior"].clone()).unwrap();let text=law["text"].as_str().unwrap();let calls=AtomicUsize::new(0);let host_owned=AtomicUsize::new(0);
 let mut allocate=|request:NativeDecodeAllocation|{assert_eq!(request.owned_bytes,host_owned.load(Ordering::Relaxed));assert_eq!(request.next_owned_bytes,request.owned_bytes+request.bytes);assert_eq!(request.maximum_bytes,ceiling);host_owned.store(request.next_owned_bytes,Ordering::Relaxed);calls.fetch_add(1,Ordering::Relaxed);Ok(())};
 let mut progress=|_|true;let mut control=NativeDecodeControl::new_forwarded(ceiling,&mut progress,&mut allocate);assert_eq!(control.copy_bytes(&prior).unwrap(),prior);let output=control.copy_text(text).unwrap();assert_eq!(serde_json::to_value(output).unwrap(),serde_json::to_value(text).unwrap());
 let receipt=control.pause().unwrap();let mut next=|_|true;let mut resumed=NativeForwardedDecodeControl::resume(receipt,&mut next).unwrap();assert_eq!(resumed.copy_text(law["tail"].as_str().unwrap()).unwrap(),"x");assert_eq!(resumed.owned_bytes(),law["expected"].as_u64().unwrap()as usize);assert_eq!(host_owned.load(Ordering::Relaxed),resumed.owned_bytes());assert_eq!(calls.load(Ordering::Relaxed),3);
}
#[test]
fn decoder_refused_allocation_and_original_observers_preserve_zero_ownership(){
 let law=fixture();let bytes=law["refusedBytes"].as_u64().unwrap()as usize;let source="x".repeat(bytes);let pointer=source.as_ptr();
 for kind in [ValueRefusalKind::OwnershipLimit,ValueRefusalKind::Canceled]{let calls=AtomicUsize::new(0);let mut allocate=|request:NativeDecodeAllocation|{assert_eq!(request.owned_bytes,0);calls.fetch_add(1,Ordering::Relaxed);Err(ValueError::literal(kind,"original decoder allocation refused"))};let mut receipt=NativeForwardedDecodeContinuation::new(bytes,&mut allocate);let mut progress=|_|true;assert_eq!(receipt.decode(&mut progress,|control|control.copy_text(&source)).unwrap_err().kind,kind);assert_eq!(receipt.owned_bytes(),0);assert_eq!(calls.load(Ordering::Relaxed),1);assert_eq!(source.as_ptr(),pointer);}
 let calls=AtomicUsize::new(0);let original=AtomicUsize::new(0);let secondary=AtomicUsize::new(0);let mut allocate=|_:NativeDecodeAllocation|{calls.fetch_add(1,Ordering::Relaxed);Ok(())};let mut receipt=NativeForwardedDecodeContinuation::new(bytes,&mut allocate);let mut progress=|_|{original.fetch_add(1,Ordering::Relaxed);true};let mut canceled=|_|{secondary.fetch_add(1,Ordering::Relaxed);false};assert_eq!(receipt.decode(&mut progress,|control|control.scoped_observer(&mut canceled,|child|child.copy_text(&source))).unwrap_err().kind,ValueRefusalKind::Canceled);assert_eq!(calls.load(Ordering::Relaxed),0);assert_eq!(original.load(Ordering::Relaxed),1);assert_eq!(secondary.load(Ordering::Relaxed),1);assert_eq!(receipt.owned_bytes(),0);
}
#[test]
fn decoder_original_retirement_slot_survives_pause_and_refused_hops(){
 let law=fixture();let bytes=law["wrapperBytes"].as_u64().unwrap()as usize;let calls=AtomicUsize::new(0);let mut allocate=|_:NativeDecodeAllocation|{calls.fetch_add(1,Ordering::Relaxed);Ok(())};let mut recipient=NativeDecodeRetirementRecipient::new();let mut progress=|_|true;let mut control=NativeDecodeControl::new_forwarded(bytes*3,&mut progress,&mut allocate);control.install_retirement_recipient(&mut recipient).unwrap();let mut receipt=control.pause().unwrap();let mut next=|_|true;
 let error=receipt.decode(&mut next,|control|control.with_retirement_owner(bytes,|_|(Err::<(),_>(ValueError::literal(ValueRefusalKind::InvalidValue,"partial owner refused")),None))).unwrap_err();assert_eq!(error.kind,ValueRefusalKind::InvalidValue);assert_eq!(receipt.owned_bytes(),bytes);
 receipt.decode(&mut next,|control|control.scoped_observer(&mut | _ |true,|child|child.with_retirement_owner(bytes,|_|(Ok(()),None)))).unwrap();assert_eq!(receipt.owned_bytes(),bytes*2);assert_eq!(calls.load(Ordering::Relaxed),2);drop(receipt);assert!(!recipient.has_owner());
}

#[test]
fn decoder_refused_partial_owner_returns_to_the_same_original_recipient(){
 use crate::{ErasedSnapshotRetirement,retained_clone::{RetainedCloneGrant,RetainedCloneProgress,RetainedCloneStep}};
 use std::sync::Arc;
 struct Owner{bytes:Option<Vec<u8>>,drops:Arc<AtomicUsize>}
 impl Drop for Owner{fn drop(&mut self){assert!(self.bytes.is_none());self.drops.fetch_add(1,Ordering::Relaxed);}}
 impl ErasedSnapshotRetirement for Owner{
  fn next_demand(&self,_:usize)->Result<crate::RetirementDemand,ValueError>{Ok(crate::RetirementDemand{copy_bytes:if self.bytes.is_some(){std::mem::size_of::<Option<Vec<u8>>>()}else{0},release_bytes:self.bytes.as_ref().map_or(0,Vec::capacity),depth:1,..Default::default()})}
  fn close_step(&mut self,grant:RetainedCloneGrant)->Result<RetainedCloneStep,ValueError>{if grant.maximum_items==0{return Ok(RetainedCloneStep::Progress(Default::default()))}let released=self.next_release_byte_demand()?;if released>grant.maximum_release_bytes{return Err(ValueError::literal(ValueRefusalKind::OwnershipLimit,"original retained release grant refused"))}let copy=std::mem::size_of::<Option<Vec<u8>>>();if grant.maximum_copy_bytes<copy{return Ok(RetainedCloneStep::Progress(Default::default()))}self.bytes.take();Ok(RetainedCloneStep::Complete(RetainedCloneProgress{copied_items:1,copied_bytes:copy,released_bytes:released,..Default::default()}))}
  fn terminal_is_empty(&self)->bool{self.bytes.is_none()}
  fn next_copy_byte_demand(&self)->Result<usize,ValueError>{Ok(if self.bytes.is_some(){std::mem::size_of::<Option<Vec<u8>>>()}else{0})}
  fn next_capacity_byte_demand(&self,_:usize)->Result<usize,ValueError>{Ok(0)}
  fn next_release_byte_demand(&self)->Result<usize,ValueError>{Ok(self.bytes.as_ref().map_or(0,Vec::capacity))}
  fn next_depth_demand(&self)->Result<usize,ValueError>{Ok(1)}
 }
 let law=fixture();let payload:Vec<u8>=serde_json::from_value(law["retainedPayload"].clone()).unwrap();let drops=Arc::new(AtomicUsize::new(0));let bytes=std::mem::size_of::<Owner>()+payload.len();let calls=AtomicUsize::new(0);let mut allocate=|_:NativeDecodeAllocation|{calls.fetch_add(1,Ordering::Relaxed);Ok(())};let mut recipient=NativeDecodeRetirementRecipient::new();let mut receipt=NativeForwardedDecodeContinuation::new(bytes,&mut allocate);receipt.install_retirement_recipient(&mut recipient).unwrap();let mut progress=|_|true;
 let error=receipt.decode(&mut progress,|control|control.with_retirement_owner(std::mem::size_of::<Owner>(),|control|match control.copy_bytes(&payload){Err(error)=>(Err::<(),_>(error),None),Ok(owned)=>(Err(ValueError::literal(ValueRefusalKind::InvalidValue,"original typed construction refused")),Some(Box::new(Owner{bytes:Some(owned),drops:drops.clone()})as Box<dyn ErasedSnapshotRetirement>))})).unwrap_err();assert_eq!(error.kind,ValueRefusalKind::InvalidValue);assert_eq!(receipt.owned_bytes(),bytes);assert_eq!(calls.load(Ordering::Relaxed),2);assert_eq!(drops.load(Ordering::Relaxed),0);drop(receipt);assert!(recipient.has_owner());
 let denied=RetainedCloneGrant{maximum_items:1,maximum_depth:1,..Default::default()};assert_eq!(recipient.close_step(denied).unwrap().progress(),RetainedCloneProgress::default());assert_eq!(drops.load(Ordering::Relaxed),0);let granted:RetainedCloneGrant=serde_json::from_value(law["retainedCloseGrant"].clone()).unwrap();let header=law["retainedCloseHeaders"].as_array().unwrap().iter().find(|row|row["nativeWordBytes"].as_u64().unwrap()as usize==std::mem::size_of::<usize>()).unwrap();assert_eq!(std::mem::size_of::<Option<Vec<u8>>>(),header["optionalByteHeaderBytes"].as_u64().unwrap()as usize);assert_eq!(std::mem::size_of::<Option<Box<dyn ErasedSnapshotRetirement>>>(),header["ownerSlotHeaderBytes"].as_u64().unwrap()as usize);let mut total=RetainedCloneProgress::default();for _ in 0..granted.maximum_items{if recipient.terminal_is_empty(){break}let remaining=RetainedCloneGrant{maximum_items:granted.maximum_items-total.copied_items,maximum_copy_bytes:granted.maximum_copy_bytes-total.copied_bytes,maximum_capacity_bytes:granted.maximum_capacity_bytes-total.retained_capacity_bytes,maximum_release_bytes:granted.maximum_release_bytes-total.released_bytes,maximum_depth:granted.maximum_depth};assert!(recipient.next_copy_byte_demand().unwrap()<=remaining.maximum_copy_bytes);let step=recipient.close_step(remaining).unwrap();assert!(step.progress().fits(remaining));total=total.checked_add(step.progress()).unwrap();}assert!(recipient.terminal_is_empty());assert_eq!(total.copied_bytes,(header["optionalByteHeaderBytes"].as_u64().unwrap()+header["ownerSlotCloseCopyBytes"].as_u64().unwrap())as usize);assert_eq!(total.released_bytes,bytes);assert_eq!(drops.load(Ordering::Relaxed),1);
}

#[test]
fn original_decoder_text_slot_keeps_materialized_utf8_on_interior_cancellation(){
 use crate::{ErasedSnapshotRetirement,retirement::controlled::ControlledRetirement,RetainedCloneGrant,retained_clone::RetainedCloneStep};
 struct Owner{value:ControlledRetirement<String>,drops:std::sync::Arc<AtomicUsize>}
 impl Drop for Owner{fn drop(&mut self){assert!(self.value.terminal_is_empty());self.drops.fetch_add(1,Ordering::Relaxed);}}
 impl ErasedSnapshotRetirement for Owner{fn close_step(&mut self,grant:RetainedCloneGrant)->Result<RetainedCloneStep,ValueError>{self.value.step(grant)}fn terminal_is_empty(&self)->bool{self.value.terminal_is_empty()}fn next_demand(&self,body:usize)->Result<crate::RetirementDemand,ValueError>{self.value.next_demand(body)}fn next_copy_byte_demand(&self)->Result<usize,ValueError>{self.value.next_copy_byte_demand()}fn next_capacity_byte_demand(&self,copy:usize)->Result<usize,ValueError>{self.value.next_capacity_byte_demand(copy)}fn next_release_byte_demand(&self)->Result<usize,ValueError>{self.value.next_release_byte_demand()}fn next_depth_demand(&self)->Result<usize,ValueError>{self.value.next_depth_demand()}}
 let neutral:serde_json::Value=serde_json::from_str(fixture_text!("../../../🛂️allocation/🧪️tests/🧫️fixtures/🔤️receiving/🔣️.json")).unwrap();let source=neutral["unit"].as_str().unwrap().repeat(neutral["repetitions"].as_u64().unwrap()as usize);let expected=neutral["expectedBytes"].as_u64().unwrap()as usize;let cutoff=neutral["refuseAtMaterialized"].as_u64().unwrap()as usize;let grant:RetainedCloneGrant=serde_json::from_value(neutral["grant"].clone()).unwrap();let drops=std::sync::Arc::new(AtomicUsize::new(0));let ledger=AtomicUsize::new(0);let mut allocation=|request:NativeDecodeAllocation|{assert_eq!(request.owned_bytes,ledger.load(Ordering::Relaxed));ledger.store(request.next_owned_bytes,Ordering::Relaxed);Ok(())};let mut recipient=NativeDecodeRetirementRecipient::new();let mut progress=|event:crate::native_decoding::NativeDecodeProgress|!(event.total==expected&&event.completed>=cutoff);let mut native=NativeDecodeControl::new_forwarded(neutral["maximumBytes"].as_u64().unwrap()as usize,&mut progress,&mut allocation);native.install_retirement_recipient(&mut recipient).unwrap();let result=native.with_retirement_owner(std::mem::size_of::<Owner>(),|native|{let mut owner=Box::new(Owner{value:ControlledRetirement::new(String::new()).ok().unwrap(),drops:drops.clone()});let result=native.copy_text_into(&source,owner.value.original_mut().unwrap());let partial=owner.value.original_mut().unwrap();assert_eq!(partial.len(),cutoff);assert_eq!(partial.capacity(),expected);assert_eq!(serde_json::to_value(&*partial).unwrap(),serde_json::to_value(&source[..cutoff]).unwrap());(result,Some(owner as Box<dyn ErasedSnapshotRetirement>))});assert_eq!(result.unwrap_err().kind,ValueRefusalKind::Canceled);assert_eq!(drops.load(Ordering::Relaxed),0);assert!(native.has_retirement_owner());assert_eq!(native.owned_bytes(),std::mem::size_of::<Owner>()+expected);while native.has_retirement_owner(){native.close_retirement_recipient(grant).unwrap();assert_eq!(native.owned_bytes(),ledger.load(Ordering::Relaxed));}assert_eq!(drops.load(Ordering::Relaxed),1);drop(native);assert!(!recipient.has_owner());
}



#[test]
fn allocation_effect_preserves_exact_backing_after_original_post_refusal(){
 use crate::native_decoding::NativeDecodeAllocationEvent;use crate::retirement::controlled::ControlledRetirement;use crate::RetainedCloneGrant;
 let mut pending=None;let mut submitted=0usize;let mut port=|event:NativeDecodeAllocationEvent|match event{NativeDecodeAllocationEvent::Quote(request)=>{assert!(pending.replace(request).is_none());Ok(())},NativeDecodeAllocationEvent::Post{request,actual}=>{assert_eq!(pending.take(),Some(request));submitted+=actual;Err(ValueError::literal(ValueRefusalKind::Canceled,"original allocation post refused"))},NativeDecodeAllocationEvent::Cancel(request)=>{assert_eq!(pending.take(),Some(request));Ok(())}};let mut issuer=crate::native_decoding::NativeDecodeAllocationIssuer::new();let mut loan=issuer.loan(&mut port);let mut observe=|_|true;let mut native=NativeDecodeControl::new_forwarded(16,&mut observe,&mut loan);let mut output=None;let mut actual=None;let mut unwind=None;let result=native.allocate_effect(16,&mut actual,&mut unwind,&mut |actual|{let layout=std::alloc::Layout::array::<u64>(2).unwrap();let pointer=unsafe{std::alloc::alloc(layout)}.cast::<u64>();if pointer.is_null(){return Err(ValueError::literal(ValueRefusalKind::AllocationFailed,"fixture allocation refused"))}output=Some(unsafe{Vec::from_raw_parts(pointer,0,2)});*actual=Some(layout.size());Ok(())});assert_eq!(native.owned_bytes(),16);assert_eq!(result.actual,Some(16));assert!(result.primary.is_none());assert!(result.extent_refusal.is_none());assert_eq!(result.settlement_refusal.as_ref().unwrap().message.as_ref(),"original allocation post refused");assert!(output.is_some());assert!(unwind.is_none());drop(native);assert_eq!(submitted,16);assert!(pending.is_none());let grant=RetainedCloneGrant{maximum_items:1024,maximum_copy_bytes:65536,maximum_capacity_bytes:65536,maximum_release_bytes:65536,maximum_depth:64};let mut vector=ControlledRetirement::new(output.take().unwrap()).ok().unwrap();while !vector.terminal_is_empty(){vector.step(grant).unwrap();}let mut error=ControlledRetirement::new(result).ok().unwrap();while !error.terminal_is_empty(){error.step(grant).unwrap();}
}

#[test]
fn allocation_quote_denial_and_failed_effect_leave_original_ledger_empty(){
 use crate::native_decoding::NativeDecodeAllocationEvent;for denied in [true,false]{let mut pending=None;let mut quotes=0usize;let mut canceled=0usize;let mut port=|event:NativeDecodeAllocationEvent|match event{NativeDecodeAllocationEvent::Quote(request)=>{quotes+=1;if denied{return Err(ValueError::literal(ValueRefusalKind::OwnershipLimit,"original quote denied"))}assert!(pending.replace(request).is_none());Ok(())},NativeDecodeAllocationEvent::Cancel(request)=>{assert_eq!(pending.take(),Some(request));canceled+=1;Ok(())},NativeDecodeAllocationEvent::Post{..}=>panic!("no-effect action cannot post")};let mut issuer=crate::native_decoding::NativeDecodeAllocationIssuer::new();let mut loan=issuer.loan(&mut port);let mut observe=|_|true;let mut native=NativeDecodeControl::new_forwarded(16,&mut observe,&mut loan);let mut called=false;let mut actual=None;let mut unwind=None;let outcome=native.allocate_effect(16,&mut actual,&mut unwind,&mut |_|{called=true;Err(ValueError::literal(ValueRefusalKind::Canceled,"canceled before allocation"))});if denied{assert!(outcome.quote_refusal.is_some());assert!(outcome.primary.is_none())}else{assert!(outcome.primary.is_some());assert!(outcome.quote_refusal.is_none())}assert!(outcome.extent_refusal.is_none());assert!(outcome.settlement_refusal.is_none());assert!(actual.is_none());assert!(unwind.is_none());assert_eq!(native.owned_bytes(),0);drop(native);assert_eq!(quotes,1);assert_eq!(canceled,usize::from(!denied));assert_eq!(called,!denied);assert!(pending.is_none());let grant=crate::RetainedCloneGrant{maximum_items:1024,maximum_copy_bytes:65536,maximum_capacity_bytes:65536,maximum_release_bytes:65536,maximum_depth:64};let mut owner=crate::retirement::controlled::ControlledRetirement::new(outcome).ok().unwrap();while !owner.terminal_is_empty(){owner.step(grant).unwrap();}}
}

#[test]
fn allocation_effect_panic_retains_backing_and_post_refusal_in_caller_slots(){
 use crate::native_decoding::NativeDecodeAllocationEvent;let mut pending=None;let mut submitted=0usize;let mut port=|event:NativeDecodeAllocationEvent|match event{NativeDecodeAllocationEvent::Quote(request)=>{assert!(pending.replace(request).is_none());Ok(())},NativeDecodeAllocationEvent::Post{request,actual}=>{assert_eq!(pending.take(),Some(request));submitted+=actual;Err(ValueError::literal(ValueRefusalKind::Canceled,"post refused during unwind"))},NativeDecodeAllocationEvent::Cancel(request)=>{assert_eq!(pending.take(),Some(request));Ok(())}};let mut issuer=crate::native_decoding::NativeDecodeAllocationIssuer::new();let mut loan=issuer.loan(&mut port);let mut observe=|_|true;let mut native=NativeDecodeControl::new_forwarded(16,&mut observe,&mut loan);let mut output=None;let mut actual=None;let mut unwind=None;let panic=std::panic::catch_unwind(std::panic::AssertUnwindSafe(||native.allocate_effect(16,&mut actual,&mut unwind,&mut |actual|{let layout=std::alloc::Layout::array::<u64>(2).unwrap();let pointer=unsafe{std::alloc::alloc(layout)}.cast::<u64>();if pointer.is_null(){return Err(ValueError::literal(ValueRefusalKind::AllocationFailed,"fixture allocation refused"))}output=Some(unsafe{Vec::from_raw_parts(pointer,0,2)});*actual=Some(layout.size());panic!("original effect panic")})));assert!(panic.is_err());assert_eq!(actual,Some(16));native.settle_allocation_progress(unwind.as_mut().unwrap(),actual).unwrap();assert_eq!(native.owned_bytes(),16);assert_eq!(unwind.as_ref().unwrap().outcome.settlement_refusal.as_ref().unwrap().message.as_ref(),"post refused during unwind");assert!(output.is_some());drop(native);assert_eq!(submitted,16);assert!(pending.is_none());let grant=crate::RetainedCloneGrant{maximum_items:1024,maximum_copy_bytes:65536,maximum_capacity_bytes:65536,maximum_release_bytes:65536,maximum_depth:64};let mut vector=crate::retirement::controlled::ControlledRetirement::new(output.take().unwrap()).ok().unwrap();while !vector.terminal_is_empty(){vector.step(grant).unwrap();}let mut error=crate::retirement::controlled::ControlledRetirement::new(unwind.take().unwrap()).ok().unwrap();while !error.terminal_is_empty(){error.step(grant).unwrap();}
}

#[test]
fn partial_allocation_keeps_requested_admission_and_actual_capacity_distinct(){
 use crate::native_decoding::NativeDecodeAllocationEvent;let mut pending=None;let mut submitted=0usize;let mut admitted=0usize;let mut quotes=0;let mut port=|event:NativeDecodeAllocationEvent|match event{NativeDecodeAllocationEvent::Quote(request)=>{assert_eq!(request.owned_bytes,admitted);assert!(pending.replace(request).is_none());quotes+=1;Ok(())},NativeDecodeAllocationEvent::Post{request,actual}=>{assert_eq!(pending.take(),Some(request));submitted+=actual;admitted=request.next_owned_bytes;Ok(())},NativeDecodeAllocationEvent::Cancel(request)=>{assert_eq!(pending.take(),Some(request));Ok(())}};let mut issuer=crate::native_decoding::NativeDecodeAllocationIssuer::new();let mut loan=issuer.loan(&mut port);let mut observe=|_|true;let mut native=NativeDecodeControl::new_forwarded(32,&mut observe,&mut loan);let mut actual=None;let mut unwind=None;let mut output=None;let first=native.allocate_effect(16,&mut actual,&mut unwind,&mut |actual|{let layout=std::alloc::Layout::array::<u8>(8).unwrap();let pointer=unsafe{std::alloc::alloc(layout)};if pointer.is_null(){return Err(ValueError::literal(ValueRefusalKind::AllocationFailed,"fixture allocation refused"))}output=Some(unsafe{Vec::from_raw_parts(pointer,0,8)});*actual=Some(8);Ok(())});assert!(first.primary.is_none()&&first.extent_refusal.is_none()&&first.settlement_refusal.is_none());assert_eq!(first.request.unwrap().bytes,16);assert_eq!(first.actual,Some(8));assert_eq!(native.owned_bytes(),16);actual=None;let second=native.allocate_effect(16,&mut actual,&mut unwind,&mut |_|Err(ValueError::literal(ValueRefusalKind::Canceled,"no effect")));assert_eq!(native.owned_bytes(),16);drop(native);assert_eq!(submitted,8);assert_eq!(quotes,2);assert!(pending.is_none());let grant=crate::RetainedCloneGrant{maximum_items:1024,maximum_copy_bytes:65536,maximum_capacity_bytes:65536,maximum_release_bytes:65536,maximum_depth:64};for error in [first,second]{let mut owner=crate::retirement::controlled::ControlledRetirement::new(error).ok().unwrap();while !owner.terminal_is_empty(){owner.step(grant).unwrap();}}let mut owner=crate::retirement::controlled::ControlledRetirement::new(output.take().unwrap()).ok().unwrap();while !owner.terminal_is_empty(){owner.step(grant).unwrap();}
}
